changed.home/workspace/Banc/live.k7/graph.k7x:
// The signal graph, as SEGMENTS: each module says where its signal goes next.
//
// There is NO LANE here, and no `nodes/` track file: a run carrying a live input and
// landing on no lane materialises its own track, the way a bus does. So this is the whole
// rig — input, fader, out. See packages/song/docs/liveProject.md.
//
// Put a module between the two and you have an effects chain, which is what this shape is
// for: `IN: ["amp"]`, `amp: ["fader"]`.
modules({
  // The input runs into the fader…
  IN: ["fader"],
  // …and the fader into the mixer's sum, where every run in every project lands. Not
  // straight to OUT: the engine sums a track into the master either way, so OUT would
  // DRAW a bypass of the master run below that does not exist.
  fader: ["MIX"],
  // The master run, which every project has: what the bar's record button captures is
  // what reaches OUT, the whole mix (packages/song/docs/outputRecording.md).
  MIX: ["OUT"],
})

changed.home/workspace/Banc/live.k7/nodes/IN.k7x:
// The live input off the audio interface — what this project exists to hear.
//
// It names NO channel, and that is deliberate: which socket you are plugged into is a fact
// about your RIG, and no scaffold can guess it. Until you choose one the project says so —
// "no channel — it feeds nothing" — which is the one thing worth being told about a rig
// that is not making a sound yet. Pick it on the node's card, or write it here:
//
//     channel([1])        // 1-based; a PAIR for a stereo input, e.g. [1, 2]
//     channel("guitar")   // …or a label from the machine's preferences.yaml (channels.in),
//                         // which is the spelling that survives another machine
//
// `monitor("on")` is what makes it audible without arming anything.
io("in")
monitor("on")
// …and a trim in dB, applied at the interface ahead of everything: 0 is unity.
gain(0)

// The rig's fader — one USE of the SHARED strip: a level in dB, a pan and three bands,
// which is what a track's level is everywhere in this app. It comes with the face the
// library module carries, so the card draws a fader and four knobs rather than nothing.
//
// A node is where a param belongs, so a second input later gets its own fader without
// either touching the other's level.
extends("@meta/audio/mixer")
params({
  // Unity, in DECIBELS: -60 is silence and +6 the top. Never 0..1, which would look like
  // it worked and send half a dB for half a fader.
  Volume: 0,
})

changed.home/workspace/Banc/live.k7/project.k7x:
// A LIVE rig: something plugged in, heard through this machine.
//
// It declares no `surfaces/` — no timeline, no viewport, no desk — and that is the whole
// of what makes it this shape rather than another. A project draws what it DECLARES, so
// this one opens on its graph and nothing else. See packages/song/docs/liveProject.md.
//
// It holds no material either: no `clips/`, no `sequences/`. Nothing is arranged, so
// nothing warns about an arrangement that is not drawn.
project({
  name: "Banc",
  // Kept although nothing is arranged: the metronome counts in it, and so does a
  // delay whose time is written in beats.
  tempo: 120,
  sampleRate: 48000,
})

changed.home/workspace/Banc/live.k7/settings.k7x:
// The metronome is OFF: a rig you play through is not a rig you record to a click.
metronome(false)
count_in(1)

