  // Kept although nothing is arranged: the metronome counts in it, and so does a
  // delay whose time is written in beats.
  tempo: 120,
  sampleRate: 48000,
})

tree.home/workspace/Banc/live.k7/settings.k7x:
// The metronome is OFF: a rig you play through is not a rig you record to a click.
metronome(false)
count_in(1)

// The rig's fader — one USE of the SHARED strip: a level in dB, a pan and three bands,
// which is what a track's level is everywhere in this app. It comes with the face the
// library module carries, so the card draws a fader and four knobs rather than nothing.
//
// A node is where a param belongs, so a second input later gets its own fader without
// either touching the other's level.
extends("@meta/audio/mixer")
params({
  // Unity, in DECIBELS: -60 is silence and +6 the top. Never 0..1, which would look like
  // it worked and send half a dB for half a fader.
  Volume: 0,
})

tree.home/workspace/Banc/live.k7/graph.k7x:
// The bench, with the library chain "@k7-core/solo" COPIED between the input and the fader.
// Nothing here is saved by itself: `chain save <name>` writes the run into your chains. See apps/k7/backend-rs/docs/banc.md.
modules({ fader: ["MIX"], MIX: ["OUT"], IN: ["verb"], verb: ["fader"] })

tree.home/workspace/Banc/live.k7/nodes/IN.k7x:
// The live input off the audio interface — what this project exists to hear.
//
// It names NO channel, and that is deliberate: which socket you are plugged into is a fact
// about your RIG, and no scaffold can guess it. Until you choose one the project says so —
// "no channel — it feeds nothing" — which is the one thing worth being told about a rig
// that is not making a sound yet. Pick it on the node's card, or write it here:
//
//     channel([1])        // 1-based; a PAIR for a stereo input, e.g. [1, 2]
//     channel("guitar")   // …or a label from the machine's preferences.yaml (channels.in),
//                         // which is the spelling that survives another machine
//
// `monitor("on")` is what makes it audible without arming anything.
io("in")
monitor("on")
// …and a trim in dB, applied at the interface ahead of everything: 0 is unity.
gain(0)

// The rig's fader — one USE of the SHARED strip: a level in dB, a pan and three bands,
// which is what a track's level is everywhere in this app. It comes with the face the
// library module carries, so the card draws a fader and four knobs rather than nothing.
//
// A node is where a param belongs, so a second input later gets its own fader without
// either touching the other's level.
extends("@meta/audio/mixer")
params({
  // Unity, in DECIBELS: -60 is silence and +6 the top. Never 0..1, which would look like
  // it worked and send half a dB for half a fader.
  Volume: 0,
})

